#if UNITY_EDITOR
using System;
using System.Collections;
using System.Collections.Generic;
using System.Linq;
using System.Reflection;
using NUnit.Framework;
using UnityEditor.SceneManagement;
using UnityEngine;
using UnityEngine.SceneManagement;
using UnityEngine.TestTools;

public sealed class CornholeBankScoreLifecycleTests
{
    const BindingFlags Any=BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic;
    static Type Runtime(string name)=>Type.GetType("LWS.TruckSports."+name+", Assembly-CSharp",true);
    static object Get(object owner,string name)=>owner.GetType().GetField(name,Any) is FieldInfo field?field.GetValue(owner):owner.GetType().GetProperty(name,Any).GetValue(owner);
    static void Set(object owner,string name,object value)=>owner.GetType().GetField(name,Any).SetValue(owner,value);
    static object Call(object owner,string name,params object[] args)=>owner.GetType().GetMethods(Any).Single(m=>m.Name==name&&m.GetParameters().Length==args.Length).Invoke(owner,args);
    static Rect Bounds(RectTransform rect){var p=new Vector3[4];rect.GetWorldCorners(p);return Rect.MinMaxRect(p[0].x,p[0].y,p[2].x,p[2].y);}
    public sealed class Receipts{public readonly List<object> items=new List<object>();public void Record(object receipt)=>items.Add(receipt);}
    [UnityTest,Timeout(600000)]public IEnumerator FourOriginalPhysicalCoursesPublishOnlyFinalizedBankedPoints()
    {
        var prefs=(IDisposable)Runtime("SportsPrefs").GetMethod("IsolateValidation").Invoke(null,new object[]{"CornholeOriginalBankedAwards"});Runtime("SportsParticipantRegistry").GetMethod("ForgetCache").Invoke(null,null);var isolation=new GameObject("Four original physical Cornhole courses acceptance");UnityEngine.Object.DontDestroyOnLoad(isolation);isolation.AddComponent(Runtime("SportsProbeInputIsolation"));Component match=null;EventInfo signal=null;Delegate subscription=null;var observed=new Receipts();
        try
        {
            EditorSceneManager.LoadSceneInPlayMode("Assets/TruckCornhole/Scenes/TruckCornhole.unity",new LoadSceneParameters(LoadSceneMode.Single));yield return null;yield return null;match=(Component)UnityEngine.Object.FindAnyObjectByType(Type.GetType("LWS.TruckCornhole.CornholeMatch, Assembly-CSharp",true));Set(Get(match,"setup"),"count",4);Call(match,"AllAI");var players=(Array)Get(Get(match,"setup"),"players");for(int i=0;i<4;i++){var player=players.GetValue(i);Set(player,"difficulty",Enum.Parse(Get(player,"difficulty").GetType(),"Hard"));Runtime("SportsParticipantRegistry").GetMethod("Rename").Invoke(null,new[]{Get(player,"participantId"),(object)"Same Cornhole Name",Get(player,"color"),true});}Call(match,"RefreshParticipants",false);Runtime("SportsCameraOptions").GetMethod("Set").Invoke(null,new object[]{true});var presets=Get(match,"weatherPresets");var clear=((Array)Get(presets,"entries")).Cast<object>().FirstOrDefault(p=>(string)Get(p,"displayName")=="Clear");if(clear!=null)Call(presets,"Select",Get(clear,"id"));signal=match.GetType().GetEvent("ScoreConfirmed");subscription=Delegate.CreateDelegate(signal.EventHandlerType,observed,typeof(Receipts).GetMethod("Record"));signal.AddEventHandler(match,subscription);Assert.That(Call(match,"StartMatch"),Is.True);Time.timeScale=4;float deadline=Time.realtimeSinceStartup+480;var courses=(Array)Get(match,"courses");bool sawProvisional=false;
            while(observed.items.Count==0&&!(bool)Get(match,"Finished")&&Time.realtimeSinceStartup<deadline){if((int)Get(match,"RoundFinalizations")==0){Assert.That(observed.items,Is.Empty,"Provisional contacts do not bank match points.");sawProvisional|=courses.Cast<object>().Any(course=>(int)Get(course,"Provisional")>0);}yield return new WaitForFixedUpdate();}
            Assert.That(observed.items.Count,Is.GreaterThan(0),"Original physical four-delivery courses must finalize real positive points.");Assert.That(sawProvisional,Is.True);Assert.That(Get(match,"RoundBreak"),Is.True);((Behaviour)match).enabled=false;Time.timeScale=0;var totals=(int[])((int[])Get(match,"totals")).Clone();var sums=new double[4];var ids=new HashSet<string>();int count=observed.items.Count;
            foreach(var receipt in observed.items){int slot=(int)Get(receipt,"Slot");Assert.That(slot,Is.InRange(0,3));Assert.That(ids.Add((string)Get(receipt,"EventId")),Is.True);Assert.That(Get(receipt,"ParticipantId"),Is.EqualTo(Get(players.GetValue(slot),"participantId")));Assert.That(Get(receipt,"DisplayName"),Is.EqualTo("Same Cornhole Name"));Assert.That(Get(receipt,"MatchId"),Is.EqualTo(Get(match,"MatchId")));Assert.That(Get(receipt,"IsTeam"),Is.False);Assert.That(Get(receipt,"RoundEnded"),Is.True);double delta=(double)Get(receipt,"Delta");Assert.That(delta,Is.GreaterThan(0).And.LessThanOrEqualTo(12));Assert.That(delta,Is.EqualTo((double)((int[])Get(match,"lastRound"))[slot]));sums[slot]+=delta;Assert.That(Get(receipt,"Total"),Is.EqualTo(sums[slot]));Assert.That((int)Get(courses.GetValue(slot),"RoundLocks"),Is.GreaterThan(0));}
            for(int i=0;i<4;i++)Assert.That(sums[i],Is.EqualTo(totals[i]));Assert.That(Get(Get(match,"ScoreJournal"),"Count"),Is.EqualTo(count));var panels=((Component)Get(match,"menus")).GetComponentsInChildren(Runtime("SportsScorePresentation"),true).Cast<Component>().ToArray();Assert.That(panels.Length,Is.EqualTo(1));var panel=panels[0];Assert.That(Get(panel,"alternateSession"),Is.SameAs(match));Time.timeScale=1;deadline=Time.realtimeSinceStartup+20;while(Get(panel,"LastPresented")==null&&Time.realtimeSinceStartup<deadline)yield return null;Assert.That(observed.items,Does.Contain(Get(panel,"LastPresented")));var animator=(Animator)Get(panel,"notificationAnimator");yield return new WaitForSeconds(animator.runtimeAnimatorController.animationClips.Single(x=>x.name=="Notification_In").length+.03f);Time.timeScale=0;yield return null;Assert.That(((CanvasGroup)Get(panel,"visibility")).alpha,Is.EqualTo(1));var headers=(Array)Get(Get(match,"menus"),"headers");foreach(var label in headers.Cast<Component>())Assert.That(Bounds((RectTransform)panel.transform).Overlaps(Bounds((RectTransform)label.transform)),Is.False,"Shared banked notification clears original four-course headers.");var cameras=courses.Cast<object>().Select(course=>(Camera)Get(Get(course,"chase"),"view")).ToArray();Assert.That(cameras.Count(camera=>camera.enabled),Is.EqualTo(4));var save=Runtime("SportsControlledCapture").GetMethods().Single(m=>m.Name=="Save"&&m.GetParameters().Length==6);foreach(var size in new[]{new Vector2Int(1280,720),new Vector2Int(1920,1080)})save.Invoke(null,new object[]{((Component)Get(match,"menus")).GetComponent<Canvas>(),cameras,size.x,size.y,"Logs/TruckSports/PlaytestRepair/CornholeBankAwards/actual-four-courses-"+size.y+".png",null});Assert.That(Get(Get(match,"ScoreJournal"),"Count"),Is.EqualTo(count));string old=(string)Get(match,"MatchId");((Behaviour)match).enabled=true;Call(match,"ChangeSetup");Assert.That(Call(match,"StartMatch"),Is.True);yield return null;Assert.That(Get(match,"MatchId"),Is.Not.EqualTo(old));Assert.That(Get(Get(match,"ScoreJournal"),"Count"),Is.Zero);Assert.That(Get(panel,"LastPresented"),Is.Null);TestContext.WriteLine("ACTUAL_CORNHOLE_BANK receipts="+count+" totals="+string.Join(",",totals)+"; four actual original NWH/PhysX courses, provisional points not banked, original finalized deltas, duplicate names, saved Heat/header clearance and rematch. No injected score/poses/forces/finishes; fourAI cameras are not human device testing.");
        }
        finally{Time.timeScale=1;if(match!=null){if(subscription!=null)signal.RemoveEventHandler(match,subscription);((Behaviour)match).enabled=true;Call(match,"ChangeSetup");}UnityEngine.Object.DestroyImmediate(isolation);prefs.Dispose();Runtime("SportsParticipantRegistry").GetMethod("ForgetCache").Invoke(null,null);}
    }
}
#endif
